import{_ as i,o as t,c as a,a2 as l}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"Version 1.0.0.25 Launched","description":"","frontmatter":{},"headers":[],"relativePath":"change-log/release/version-1.0.0.26-launched.md","filePath":"change-log/release/version-1.0.0.26-launched.md"}'),o={name:"change-log/release/version-1.0.0.26-launched.md"};function n(d,e,r,s,c,u){return t(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="version-1-0-0-25-launched" tabindex="-1">Version 1.0.0.25 Launched <a class="header-anchor" href="#version-1-0-0-25-launched" aria-label="Permalink to &quot;Version 1.0.0.25 Launched&quot;">​</a></h1><p>11th July 2025</p><h4 id="api-and-sdk-updates" tabindex="-1">API and SDK Updates <a class="header-anchor" href="#api-and-sdk-updates" aria-label="Permalink to &quot;API and SDK Updates&quot;">​</a></h4><ul><li>Upgraded Tradeboard Python SDK version to 1.0.19 to support Expiry API.</li><li>Added Expiry Dates API for Futures and Options Instruments.</li><li>Updated Ticker API Documentation.</li><li>Removed Ticker API Direct Method; now only date range restricted for large queries in Ticker API.</li><li>Updated Historical Direct Method for Fyers.</li><li>Implemented Historical Data Access for Amiquotes using Ticker API Direct Method.</li><li>Updated Tradeboard SDK - Python version to support New Search API.</li><li>Search API Implementation.</li><li>Added OI (Open Interest) in quotes and depth REST APIs for XTS Brokers.</li><li>Removed <code>include_oi</code> parameter and updated OI for Angel and Zerodha.</li><li>Implemented Open Interest Dynamic Handling.</li><li>Angel OI included in REST API quote, history, and websocket snap quote.</li><li>Ibulls Rest API - Market Data Update.</li><li>Ibulls Rest API - Place market order Update.</li><li>Ibulls Rest API - Placesmartorder Fixed.</li><li>Updated Aliceblue RestAPI - OI added in depth and quotes.</li></ul><h4 id="broker-integrations-and-fixes" tabindex="-1">Broker Integrations and Fixes <a class="header-anchor" href="#broker-integrations-and-fixes" aria-label="Permalink to &quot;Broker Integrations and Fixes&quot;">​</a></h4><ul><li>Zerodha: <ul><li>Websocket&#39;s Index data Fetch Update.</li><li>Index market data Fixed.</li><li>Websocket integration in Tradeboard (initial commit).</li><li>Fix Zerodha Adapter Logger.</li><li>Centralized Logging Fix.</li></ul></li><li>Dhan: <ul><li>Quote Data Fixed.</li><li>Websocket market Depth Update.</li><li>Ticker header and LTP update.</li><li>Websocket and Tradeboard&#39;s mode mapping fixed.</li><li>Websocket LTP marketdata Fixed.</li><li>Websocket marketfeed Update.</li><li>Websocket Integration Initial Commit.</li><li>Websocket reconnection issue fixed.</li><li>Websocket 20 level depth mode initial commit.</li><li>Websocket reconnection initial commit.</li><li>Sandbox Correlation ID issue fix.</li><li>PlaceSmartOrders Correlation ID fix.</li><li>Invalid Login Credentials fix.</li><li>Sandbox fix.</li><li>20 level token mapping Update.</li><li>20 level parsing Update.</li><li>Updated Dhan Websockets.</li><li>Websocket 20 level depth fixed.</li></ul></li><li>Aliceblue: <ul><li>Authentication flow Fixed.</li><li>Authentication Fixed.</li><li>Common Index symbol Update.</li><li>Websocket Auth Fixed.</li><li>Websocket - Initial commit.</li><li>RestAPI - Marketdata Update.</li><li>RestAPI - NFO/BFO symbol token fixed.</li><li>Websocket- NFO/BFO Symbol lookup fixed.</li><li>Websocket - LTP and Depth Fixed.</li><li>Websocket - Quote Fixed, Partial fix of Depth and LTP.</li></ul></li><li>Flattrade: <ul><li>Adapter registry fix &amp; <code>{symbol}_{exchange}_{mode_str}</code> matching Tradeboard proxy and other brokers &amp; Added more debug logs.</li><li>Basic Flattrade WSS (WebSocket Secure).</li><li>Fixing Holdings.</li><li>WSS completed.</li><li>Updated HTTP/1.1 fallback for Flattrade broker.</li><li>Fix: Quote and Depth Snapshot Management Implementation in Realtime Websockets.</li><li>Fix: Env Variable Wrong format Detection.</li></ul></li><li>Upstox: <ul><li>Updated <code>Upstox Data.py</code> Historical Data to Returns IST timestamps → Converts to UTC (sends UTC to API).</li><li>Updated central log fix for <code>upstox data.py</code>.</li></ul></li><li>Shoonya: <ul><li>Websockets Implementation.</li><li>Fix: Websocket for Depth and Quote Fix.</li><li>Fix: Updated Shoonya Adapter for incremental websocket data for quotes and depth.</li></ul></li><li>Ibulls: <ul><li>OI added for Ibulls.</li><li>Added Ibulls in <code>.sample.env</code> and <code>install.sh</code>.</li><li>Websocket - Urls Update.</li><li>Websocket - Depth Update.</li><li>Websocket - Quote and LTP for derivatives Update.</li><li>Websocket - Quote Update.</li><li>Websocket - LTP Update.</li><li>Websockets - Authentication and subscription Update.</li><li>Websocket - Initial Commit.</li></ul></li><li>Kotak: <ul><li>Fixing the Funds to two decimals.</li><li>Updated Kotak master contract with newer Instrument List Version.</li></ul></li><li>XTS Brokers: <ul><li>Updated XTS brokers list in <code>install.sh</code>.</li><li>Wisdom XTS websocket integration.</li><li>Jainam XTS websocket Integration.</li><li>IIFL websocket Integration.</li><li>FivepaisaXTS websocket Integration.</li><li>XTS brokers list added.</li></ul></li><li>Compositedge: <ul><li>Login Fixed and Websocket integrated.</li><li>Websocket - Initial commit.</li><li></li></ul></li></ul><h4 id="security-enhancements-and-fixes" tabindex="-1">Security Enhancements and Fixes <a class="header-anchor" href="#security-enhancements-and-fixes" aria-label="Permalink to &quot;Security Enhancements and Fixes&quot;">​</a></h4><ul><li>Updated Secure flag cookie.</li><li>Updated Referrer-Policy and Permissions-Policy.</li><li>Updating CSRF Token to View Strategy in Chartink and Strategy Management.</li><li>Fixing CSRF issue with Analyzer Mode.</li><li>Updated CSRF Audit Docs after fixing logout vulnerability.</li><li>Updated CSRF fix in the <code>tradingview.html</code> and also migrating logout from get to post request for CSRF security concerns.</li><li>CSRF Audit Report.</li><li>Updated CSRF testing and documentation.</li><li>Update the CSRF Config parameters to <code>.sample.env</code>.</li><li>CSRF Implementation.</li><li>FIX: updated CSRF Fix for Exit Position in <code>/positons</code> route.</li><li>Fixing CSRF in Close All Open Positions.</li><li>Updated CSRF fix for Strategy Deletion.</li><li>Fix: Adding CSRF Exemption for Chartink and Trading Strategy Webhook.</li><li>Security Fix: Removed rate limiting from logout endpoint.</li><li>Fix: Adding GET Support for Logout Requests for backward compatibility.</li><li>Fix: Duplicate Session Fix, Moving cookies to environmental file.</li></ul><h4 id="major-enhancement-central-logging" tabindex="-1">Major Enhancement: Central Logging <a class="header-anchor" href="#major-enhancement-central-logging" aria-label="Permalink to &quot;Major Enhancement: Central Logging&quot;">​</a></h4><p>Central Logging has been implemented as a major enhancement in Tradeboard, significantly improving how logs are managed and providing a more robust and efficient system. This initiative involved a substantial refactoring effort, with approximately 2000+ lines of previous <code>print</code> statements now successfully migrated to the new central logging system.</p><ul><li>Central Logging Implemented: <ul><li>A comprehensive effort to migrate various components and brokers to a unified, centralized logging system. This foundational change streamlines log collection and analysis.</li><li>Implementation of centralized logging across numerous brokers, including Zerodha, Upstox, Dhan, Kotak, 5paisa/Fivepaisaxts, Paytm, Flattrade, Shoonya, Tradejini, Aliceblue, Compositedge, Firstock, Groww, IIFL, Wisdom, Zebu, Pocketful, and Jainam, ensuring consistent logging practices across the platform.</li><li>Updated documentation to thoroughly reflect the new centralized logging system, aiding developers and users in understanding its functionality.</li></ul></li><li>Bug Fixes Issued to Central Logging: <ul><li>Addressed specific issues with the Zerodha Adapter Logger and general logging imports, ensuring accurate log capture.</li><li>Resolved centralized logging issues for various brokers and their specific modules, including <code>funds.py</code>, <code>Upstox data.py</code>, Aliceblue, Compositedge, 5paisa, Paytm, Flattrade, Zerodha, Angel, Shoonya, Tradejini, Dhan, Kotak, Fivepaisaxts, IIFL, Wisdom, Zebu, Pocketful, and Jainam.</li><li>Fixed issues encountered during the migration to centralized logging in blueprints, <code>proxy_websockets</code>, services, and <code>restx_api</code> folders, ensuring a smooth transition and proper log routing.</li><li>Corrected instances of duplicate logging entries, reducing log clutter and improving readability.</li><li>Updated master contract to include central logging and resolved minor string formatting issues, ensuring data integrity within logs.</li></ul></li></ul><h4 id="general-fixes-and-improvements" tabindex="-1">General Fixes and Improvements <a class="header-anchor" href="#general-fixes-and-improvements" aria-label="Permalink to &quot;General Fixes and Improvements&quot;">​</a></h4><ul><li>Websockets: <ul><li>Websockets Dynamic broker selection Update.</li><li>Websocket dictionary iteration error Fixed.</li><li>Updated websocket examples.</li><li>Feature: Added Websocket Inspector in the Playground - updated Websocket Testing.</li></ul></li><li>Performance and Refactoring: <ul><li>Refactor: Improvements http pooling and httpx migration.</li><li>Automatically Switch Between http2/1.</li><li>Reverting to http/2 module in util and changed library package to <code>httpx[http2]</code>.</li><li>Updated <code>httpx</code> auto fallback to HTTP/1.1.</li><li>Improvements: Performance Improvements.</li><li>Database Connecting Pool Optimization for Faster Query Performance.</li></ul></li><li>General Fixes: <ul><li>ITP &amp; quote fixed.</li><li>Updating the Master Contract Download Status.</li><li>Tried fixing the ZMQ issue.</li><li>Fixing PNL in both Dashboard and TradeBook.</li><li>Accessing Env variable ZMQ_port fixed.</li><li>ZMQ port config in dotenv file fixed.</li><li>ZMQ Audit report.</li><li>Zerodha&#39;s Dynamic port binding Fixed.</li><li>Updated CSS Compilation, Tradeboard Version, and test CSRF code.</li><li>Updated Master Contract with BFO Symbols.</li><li>Fix: CSRF Token issue fix and Strategy inactivate issue fix.</li><li>Updated enhanced product enhancement.</li><li>Implementing Cancel All Orders Button in the OrderBook Page.</li><li>Reverting back: the Index Fix in Websockets.</li></ul></li></ul><h4 id="documentation-and-project-management" tabindex="-1">Documentation and Project Management <a class="header-anchor" href="#documentation-and-project-management" aria-label="Permalink to &quot;Documentation and Project Management&quot;">​</a></h4><ul><li>Update <code>README.md</code>.</li><li>Docs: Enhanced Tradeboard+ Document.</li><li>Docs: Updated Tradeboard+ Documentation.</li><li>Docs: Query Batching Optimization.</li><li>Docs: Updated Design Documents and Upgrading Jupyter Core, Requests and <code>urllib3</code> libraries.</li><li>Fix: Updated Contribution Guidelines.</li><li>Fix: Updated Contribution Documentation.</li><li>Docs: updated Contribution Guidelines and Documentation.</li><li>Docs: Enhanced Trade Management Module.</li></ul><h4 id="new-features" tabindex="-1">New Features <a class="header-anchor" href="#new-features" aria-label="Permalink to &quot;New Features&quot;">​</a></h4><ul><li>Feat: Tradeboard playground-add interactive API and WebSocket playground.</li><li>Feat: updated Tradeboard SDK - Python version to support New Search API.</li></ul>',17)])])}const g=i(o,[["render",n]]);export{m as __pageData,g as default};
